import{_ as a,o as i,c as s,ag as t}from"./chunks/framework.BnsYoRqm.js";const g=JSON.parse('{"title":"Design Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"design/decisions.md","filePath":"design/decisions.md","lastUpdated":1777148476000}'),n={name:"design/decisions.md"};function o(r,e,l,c,d,h){return i(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="design-decisions" tabindex="-1">Design Decisions <a class="header-anchor" href="#design-decisions" aria-label="Permalink to &quot;Design Decisions&quot;">​</a></h1><p>This gem is opinionated. Those opinions are part of its value.</p><h2 id="atomic-integers-not-decimal-storage" tabindex="-1">Atomic integers, not decimal storage <a class="header-anchor" href="#atomic-integers-not-decimal-storage" aria-label="Permalink to &quot;Atomic integers, not decimal storage&quot;">​</a></h2><p>The atomic value is always an integer count of the smallest unit. That keeps equality, hashing, and persistence crisp.</p><h2 id="one-class-registry-driven-types" tabindex="-1">One class, registry-driven types <a class="header-anchor" href="#one-class-registry-driven-types" aria-label="Permalink to &quot;One class, registry-driven types&quot;">​</a></h2><p>Type identity lives in the registry because adding a new symbol should be a configuration action, not a subclass ceremony.</p><h2 id="directional-rates-only" tabindex="-1">Directional rates only <a class="header-anchor" href="#directional-rates-only" aria-label="Permalink to &quot;Directional rates only&quot;">​</a></h2><p>Rates are directional because real conversion systems are directional.</p><h2 id="display-units-are-not-conversions" tabindex="-1">Display units are not conversions <a class="header-anchor" href="#display-units-are-not-conversions" aria-label="Permalink to &quot;Display units are not conversions&quot;">​</a></h2><p>Showing gold in grams is still showing gold. The type has not changed.</p><h2 id="explicit-remainder" tabindex="-1">Explicit remainder <a class="header-anchor" href="#explicit-remainder" aria-label="Permalink to &quot;Explicit remainder&quot;">​</a></h2><p><code>split</code> and <code>allocate</code> return remainder explicitly because silent distribution bakes in a business preference.</p><h2 id="lockable-global-registry" tabindex="-1">Lockable global registry <a class="header-anchor" href="#lockable-global-registry" aria-label="Permalink to &quot;Lockable global registry&quot;">​</a></h2><p>The global registry is a practical boot-time configuration surface. <code>lock!</code> exists so the convenience of a shared registry does not imply ongoing runtime mutability.</p>',14)])])}const u=a(n,[["render",o]]);export{g as __pageData,u as default};
